import * as z from 'zod'

export const NameSchema = z.string().trim().min(1)

export interface Greeter {
  greet(rawName: unknown): string
}

/** A missing or blank name is a normal outcome and yields an empty greeting rather than an error. */
export class NameGreeter implements Greeter {
  greet(rawName: unknown): string {
    const result = NameSchema.safeParse(rawName)
    return result.success ? `Hello, ${result.data}!` : ''
  }
}

export const greeter: Greeter = new NameGreeter()

