import { test } from 'node:test'
import assert from 'node:assert/strict'
import { greeter } from '../greeting.ts'

test('greets a name', () => assert.strictEqual(greeter.greet('Ada'), 'Hello, Ada!'))
test('trims surrounding whitespace only', () => {
  assert.strictEqual(greeter.greet('  Ada  '), 'Hello, Ada!')
  assert.strictEqual(greeter.greet('  Ada Lovelace  '), 'Hello, Ada Lovelace!')
})
test('missing or blank name yields empty string', () => {
  assert.strictEqual(greeter.greet(undefined), '')
  assert.strictEqual(greeter.greet('   '), '')
})

