finalSource.cli.ts:
import { z } from "zod";

const GreetingPropsSchema = z.object({
  name: z.string().trim().default(""),
});

type GreetingProps = z.input<typeof GreetingPropsSchema>;

/** Describes a greeting that can be written for a command-line user. */
export interface GreetingService {
  greet(): void;
}

/** Writes a greeting for the normalized name supplied at construction. */
export class TerminalGreetingService implements GreetingService {
  private readonly name: string;

  constructor(props: GreetingProps) {
    const validProps = GreetingPropsSchema.parse(props);
    this.name = validProps.name;
  }

  public greet(): void {
    const message = this.name.length > 0 ? `Hello, ${this.name}!` : "";
    process.stdout.write(`${message}\n`);
  }
}

const greetingService = new TerminalGreetingService({
  name: process.argv[2],
});

greetingService.greet();

