import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const cliPath = resolve(projectRoot, "cli.ts");

const cases = [
  { name: "named input", args: ["Ada"], expected: "Hello, Ada!\n" },
  { name: "trimmed input", args: [" \tAda \t "], expected: "Hello, Ada!\n" },
  { name: "missing input", args: [], expected: "\n" },
  { name: "whitespace-only input", args: [" \t\n "], expected: "\n" },
  { name: "empty input", args: [""], expected: "\n" },
];

for (const { name, args, expected } of cases) {
  test(`prints the expected bytes for ${name}`, () => {
    const result = spawnSync(process.execPath, [cliPath, ...args], {
      cwd: projectRoot,
      timeout: 5000,
    });

    assert.equal(result.error, undefined, result.error?.message);
    assert.equal(result.signal, null, `process terminated by ${result.signal}`);
    assert.equal(result.status, 0, result.stderr.toString("utf8"));
    assert.deepEqual(result.stdout, Buffer.from(expected, "utf8"));
  });
}
